/* English text for data/qcm/taa.js (TAA course questions, merged by id over the French bank).
   Names from the official English algo subjects: types / uses / operations / preconditions / axioms / with,
   is-defined-iaoi, emptylist, cons, tail, first, head, contents, next, nth, insert, delete, push, pop… */
REV.i18n.topics({
  'taa-signature': 'Signature and vocabulary',
  'taa-hierarchie': 'Types and operations: the hierarchy',
  'taa-precond': 'Preconditions',
  'taa-axiomes': 'Axioms',
  'taa-liste-rec': 'Recursive lists',
  'taa-liste-iter': 'Iterative lists',
  'taa-piles': 'Stacks',
  'taa-files': 'Queues',
  'taa-ensembles': 'Sets and multisets'
});
(function () {
  /* specification block (assets/js/spec.js): one line per argument */
  function spec() { return { code: Array.prototype.slice.call(arguments).join('\n') }; }

  var COUNTER = spec(
    'types',
    '    counter',
    'uses',
    '    integer, boolean',
    'operations',
    '    new    : → counter',
    '    incr   : counter → counter',
    '    reset  : counter → counter',
    '    value  : counter → integer',
    '    iszero : counter → boolean');
  var VECT_IJ = spec(
    'axioms',
    '    lowerlimit(v) ≤ i ≤ upperlimit(v)',
    '        ⇒ isinit(modifynth(v, i, e), i) = true',
    '    lowerlimit(v) ≤ i ≤ upperlimit(v) & lowerlimit(v) ≤ j ≤ upperlimit(v)',
    '        ⇒ isinit(modifynth(v, i, e), j) = isinit(v, j)');
  var CONCAT = spec(
    'operations',
    '    concatenate : list × list → list',
    'axioms',
    '    concatenate(emptylist, λ2) = λ2',
    '    concatenate(cons(e, λ), λ2) = cons(e, concatenate(λ, λ2))',
    'with',
    '    list λ, λ2 ; element e');
  var PRESENT = spec(
    'operations',
    '    ispresent : element × list → boolean',
    'axioms',
    '    ispresent(e, emptylist) = false',
    '    e = e′ ⇒ ispresent(e, cons(e′, λ)) = true',
    '    ???',
    'with',
    '    list λ ; element e, e′');
  var LAST = spec(
    'operations',
    '    last : list → element',
    'preconditions',
    '    last(λ) is-defined-iaoi λ ≠ emptylist',
    'axioms',
    '    last(cons(e, emptylist)) = e',
    '    λ ≠ emptylist ⇒ last(cons(e, λ)) = last(λ)',
    'with',
    '    list λ ; element e');
  var MYST_REC = spec(
    'operations',
    '    mystery : list × element → list',
    'axioms',
    '    mystery(emptylist, x) = emptylist',
    '    e = x ⇒ mystery(cons(e, λ), x) = mystery(λ, x)',
    '    e ≠ x ⇒ mystery(cons(e, λ), x) = cons(e, mystery(λ, x))',
    'with',
    '    list λ ; element e, x');
  var MYST_INV = spec(
    'operations',
    '    mystery : list → list',
    'axioms',
    '    length(mystery(λ)) = length(λ)',
    '    1 ≤ i ≤ length(λ)',
    '        ⇒ nth(mystery(λ), i) = nth(λ, length(λ) − i + 1)',
    'with',
    '    list λ ; integer i');
  var MYST_ROT = spec(
    'operations',
    '    mystery : list → list',
    'preconditions',
    '    mystery(λ) is-defined-iaoi λ ≠ emptylist',
    'axioms',
    '    length(mystery(λ)) = length(λ)',
    '    1 ≤ i < length(λ) ⇒ nth(mystery(λ), i) = nth(λ, i + 1)',
    '    nth(mystery(λ), length(λ)) = nth(λ, 1)',
    'with',
    '    list λ ; integer i');
  var MYST_SWAP = spec(
    'operations',
    '    mystery : list × integer × integer → list',
    'preconditions',
    '    mystery(λ, x, y) is-defined-iaoi 1 ≤ x ≤ length(λ) & 1 ≤ y ≤ length(λ)',
    'axioms',
    '    length(mystery(λ, x, y)) = length(λ)',
    '    i = x ⇒ nth(mystery(λ, x, y), i) = nth(λ, y)',
    '    i = y ⇒ nth(mystery(λ, x, y), i) = nth(λ, x)',
    '    1 ≤ i ≤ length(λ) & i ≠ x & i ≠ y',
    '        ⇒ nth(mystery(λ, x, y), i) = nth(λ, i)',
    'with',
    '    list λ ; integer i, x, y');
  /* mystery operation of the October 2024 midterm (class of 2029) */
  var MYST_DEL = spec(
    'operations',
    '    mystery : list × integer × integer → list',
    'preconditions',
    '    mystery(λ, x, y) is-defined-iaoi 1 ≤ x ≤ y ≤ length(λ)',
    'axioms',
    '    length(mystery(λ, x, y)) = length(λ) − y + x − 1',
    '    1 ≤ i < x ⇒ nth(mystery(λ, x, y), i) = nth(λ, i)',
    '    x ≤ i ≤ length(λ) − y + x − 1',
    '        ⇒ nth(mystery(λ, x, y), i) = nth(λ, i + y − x + 1)',
    'with',
    '    list λ ; integer i, x, y');
  var MYST_END = spec(
    'operations',
    '    mystery : list × element → list',
    'axioms',
    '    length(mystery(λ, e)) = length(λ) + 1',
    '    1 ≤ i ≤ length(λ) ⇒ nth(mystery(λ, e), i) = nth(λ, i)',
    '    i = length(λ) + 1 ⇒ nth(mystery(λ, e), i) = e',
    'with',
    '    list λ ; integer i ; element e');
  var INS_WRONG = spec(
    'axioms',
    '    length(insert(λ, k, e)) = length(λ) + 1',
    '    1 ≤ i ≤ k ⇒ nth(insert(λ, k, e), i) = nth(λ, i)',
    '    k = i ⇒ nth(insert(λ, k, e), i) = e',
    '    k < i ≤ length(λ) + 1 ⇒ nth(insert(λ, k, e), i) = nth(λ, i − 1)');

  var Q = {
    /* ================= chapter 1: abstract types ================= */
    /* ---------- signature and vocabulary ---------- */
    'taa-c1-01': { q: 'The definition of an algebraic abstract type is made of…',
      o: ['a signature and a system of axioms', 'a signature only: the axioms are optional', 'a list of types and their implementation', 'axioms only: the operations follow from them'],
      x: 'This is the opening sentence of the course: a signature (the <code>types</code>, <code>uses</code> and <code>operations</code> areas) and a system of axioms that characterizes it. The signature only gives names and profiles: without axioms, nothing says what the operations do. And the axioms need the signature to know which operations they are about.' },
    'taa-c1-02': { q: 'Which parts of a specification are <em>not</em> part of the signature?',
      o: ['<code>preconditions</code>', '<code>axioms</code>', '<code>with</code>', '<code>types</code>', '<code>uses</code>', '<code>operations</code>'],
      x: 'The signature groups the <code>types</code>, <code>uses</code> and <code>operations</code> areas: the types, defined and predefined, and the operations with their profiles. The preconditions and the axioms give the properties of the operations; the <code>with</code> part gives the type of the names used in these formulas.' },
    'taa-c1-03': { q: 'In the signature, an operation is declared by…',
      o: ['its identifier (its name) and its profile', 'its name and its axioms', 'its profile and its precondition', 'its name only: the rest is read in the axioms'],
      x: 'For each operation, you give its identifier and its profile: the types of its arguments and the type of its result, for example <code>length : list → integer</code>. The preconditions and the axioms come later, in their own parts.' },
    'taa-c1-04': { q: 'What does the profile <code>nth : list × integer → element</code> say?',
      o: ['nth takes a list and an integer, and returns an element', 'nth takes a list, and returns an integer and an element', 'nth takes an element, and returns a list and an integer', 'nth takes a list, an integer and an element'],
      x: 'Left of the arrow, the types of the arguments, separated by ×; right of it, the type of the result. You use it in the form <code>nth(λ, i)</code>. The element is what the operation returns, not an argument.' },
    'taa-c1-05': { q: 'With the profile <code>delete : list × integer → list</code>, which expression is correct?',
      o: ['<code>delete(λ, 2)</code>', '<code>delete(2, λ)</code>', '<code>delete(λ)</code>', '<code>delete(λ, 2, e)</code>'],
      x: 'The arguments go in the order of the profile: first the list, then the integer, and there must be exactly two of them. Careful: in the set type, <code>delete : element × set → set</code> takes its arguments in the other order, <code>delete(x, s)</code>. The profile always decides.' },
    'taa-c1-06': { q: 'In which order do you write the parts of the definition of an abstract type?',
      o: ['<code>types</code>, <code>uses</code>, <code>operations</code>, <code>preconditions</code>, <code>axioms</code>, <code>with</code>', '<code>types</code>, <code>operations</code>, <code>uses</code>, <code>axioms</code>, <code>preconditions</code>, <code>with</code>', '<code>with</code>, <code>types</code>, <code>uses</code>, <code>operations</code>, <code>preconditions</code>, <code>axioms</code>', '<code>types</code>, <code>uses</code>, <code>operations</code>, <code>axioms</code>, <code>preconditions</code>, <code>with</code>'],
      x: 'First the types being defined, then the types already designed (<code>uses</code>, before the operations), then the operations and their profiles. Then come the properties: the preconditions first, the axioms after. You end with <code>with</code>, which gives the type of the names used in the preconditions and the axioms.' },
    'taa-c1-07': { q: 'The profile <code>false : → boolean</code> has nothing left of the arrow. <code>false</code> is…',
      o: ['a constant: an operation with no argument', 'a badly declared operation: it is missing an argument', 'a partial operation', 'an observer'],
      x: 'Nothing before the arrow: no argument. It is a constant, written without parentheses: <code>false</code>. It is a constant of the Boolean type: it returns a value of the defined type, like <code>emptylist : → list</code> for the list or <code>emptystack : → stack</code> for the stack. It is not an observer: an observer has at least one argument of a defined type.' },
    'taa-c1-08': { q: 'Which of these operations are constants?',
      o: ['<code>emptylist : → list</code>', '<code>false : → boolean</code>', '<code>isempty : stack → boolean</code>', '<code>tail : list → list</code>', '<code>card : set → integer</code>'],
      x: 'A constant has no argument: nothing left of the arrow. It returns a value of the defined type: <code>emptylist</code> a list, <code>false</code> a boolean in the Boolean type. <code>isempty</code>, <code>tail</code> and <code>card</code> each take one argument: they are not constants.' },
    'taa-c1-09': { q: 'What do the underscores mean in <code>_^_ : integer × integer → integer</code>?',
      o: ['the operation is written between its two arguments: <code>4^2</code>', 'the operation has no argument', 'the arguments are optional', 'the operation is partial'],
      x: 'Each <code>_</code> marks the place of an argument: <code>_^_</code> is used in infix notation, <code>4^2</code>. The same goes for <code>_∈_ : element × set → boolean</code>, written <code>x ∈ s</code>. The profile does have two arguments.' },
    'taa-c1-10': { q: 'You want an operation <code>concatenate</code> that takes two lists and returns the list made of the first one followed by the second one. What is its profile?',
      o: ['<code>concatenate : list × list → list</code>', '<code>concatenate : list → list × list</code>', '<code>concatenate : list × list → list × list</code>', '<code>concatenate : list → list</code>'],
      x: 'The two given lists are the arguments: they go left of the arrow, separated by ×. The result is a single list, on the right. An operation that takes only one list cannot receive two.' },
    'taa-c1-11': { q: 'In which part of the specification do you write <code>list λ</code> and <code>integer i, k</code>?',
      o: ['<code>with</code>', '<code>types</code>', '<code>uses</code>', '<code>operations</code>'],
      x: 'You end with the <code>with</code> part, which gives the type of each name used in the preconditions and the axioms. <code>types</code> and <code>uses</code> contain type names (list, integer), not variable names like λ or i.' },
    'taa-c1-12': { q: 'A constant, like <code>emptylist : → list</code> or <code>emptystack : → stack</code>, returns a value of a predefined type.',
      x: 'False. A constant is an operation with no argument, and it returns a value of the defined type: <code>emptylist</code> is a list, <code>emptystack</code> a stack, <code>true</code> a boolean in the Boolean type. So it is an internal operation with no argument, never an observer: an observer has at least one argument of a defined type.' },
    'taa-c1-13': { q: 'With <code>delete : list × integer → list</code> and <code>length : list → integer</code>, what is the type of the term <code>length(delete(λ, 2))</code>?',
      o: ['integer', 'list', 'element', 'list × integer'],
      x: 'Read from the inside out: <code>delete(λ, 2)</code> is a list, and <code>length</code> applied to a list returns an integer. The type of a term is the result type of its outermost operation.' },

    /* ---------- hierarchy: types and operations ---------- */
    'taa-c1-14': { q: 'In a specification, a <em>predefined</em> type is…',
      o: ['a type that already exists (“already designed”), listed in <code>uses</code>', 'a new type, being designed, listed in <code>types</code>', 'a type that has no operation', 'a type listed in <code>with</code>'],
      x: 'Defined: new, being designed, written in <code>types</code>. Predefined: already exists, already designed, written in <code>uses</code>, before the operations. In the stack, <code>stack</code> is defined; <code>boolean</code> and <code>element</code> are predefined. The <code>with</code> part declares variables, not types.' },
    'taa-c1-15': { q: 'An internal operation is an operation…',
      o: ['that returns a result of a defined type', 'whose arguments are all of a defined type', 'that returns a result of a predefined type', 'that has no precondition'],
      x: 'Only the result type matters: an internal operation returns a value of the type being defined (it changes the state of the data itself). Its arguments can be of any type: <code>push : stack × element → stack</code> takes an element. A result of a predefined type is what observers return. And being partial or not has nothing to do with it.' },
    'taa-c1-16': { q: 'An observer is an operation that…',
      o: ['has at least one argument of a defined type and returns a result of a predefined type', 'returns a result of a defined type', 'has no argument', 'has only arguments of predefined types'],
      x: 'Both conditions are needed: at least one argument of the type being defined (you observe that data) and a result of a predefined type (what you learn about it). <code>length : list → integer</code> is one. An operation with no argument is a constant; a result of a defined type means an internal operation.' },
    'taa-c1-17': { q: 'In the stack type (<code>types stack</code>, <code>uses boolean, element</code>), the operation <code>top : stack → element</code> is…',
      o: ['an observer', 'an internal operation', 'a constant', 'neither internal nor an observer, since it is partial'],
      x: 'Its argument is a stack (defined type) and its result an element (predefined type, in <code>uses</code>): it is an observer. Being partial (an empty stack has no top) does not change its nature: partial and observer are two separate questions.' },
    'taa-c1-18': { q: 'In the stack type (<code>types stack</code>, <code>uses boolean, element</code>), which ones are internal operations?',
      o: ['<code>emptystack : → stack</code>', '<code>push : stack × element → stack</code>', '<code>pop : stack → stack</code>', '<code>top : stack → element</code>', '<code>isempty : stack → boolean</code>'],
      x: 'The internal operations return a stack: <code>emptystack</code> (a constant), <code>push</code> and <code>pop</code>. <code>top</code> returns an element and <code>isempty</code> a boolean, two predefined types: they are the observers of the stack.' },
    'taa-c1-19': { q: 'In the iterative list (<code>types list, box</code>, <code>uses integer, element</code>), which ones are observers?',
      o: ['<code>nth : list × integer → element</code>', '<code>length : list → integer</code>', '<code>insert : list × integer × element → list</code>', '<code>delete : list × integer → list</code>', '<code>emptylist : → list</code>'],
      x: '<code>nth</code> and <code>length</code> take a list and return a predefined type (element, integer): they are observers. <code>insert</code>, <code>delete</code> and the constant <code>emptylist</code> return a list: they are internal operations, even though <code>insert</code> and <code>delete</code> also take an integer argument.' },
    'taa-c1-20': { q: 'In the vector type (<code>types vector</code>, <code>uses integer, boolean, element</code>), <code>vect : integer × integer → vector</code> has no argument of type vector. It is…',
      o: ['an internal operation', 'an observer', 'a constant', 'an operation that cannot belong to this type'],
      x: 'To be internal, returning a result of a defined type is enough: <code>vect</code> returns a vector. The types of the arguments do not matter. It is not a constant, since it has two arguments (the limits of the vector). It is not an observer: its result is not predefined.' },
    'taa-c1-21': { q: 'In the vector type (<code>types vector</code>, <code>uses integer, boolean, element</code>), which ones are observers?',
      o: ['<code>nth : vector × integer → element</code>', '<code>isinit : vector × integer → boolean</code>', '<code>lowerlimit : vector → integer</code>', '<code>modifynth : vector × integer × element → vector</code>'],
      x: 'The first three take a vector and return a predefined type (element, boolean, integer): they are observers. <code>modifynth</code> returns a vector: it is an internal operation, like <code>vect</code>.' },
    'taa-c1-22': { q: 'In the Boolean type exercise, the specification starts with <code>types boolean</code>. There, the operation <code>not : boolean → boolean</code> is…',
      o: ['an internal operation', 'an observer', 'a constant', 'a partial operation'],
      x: 'Here, <code>boolean</code> is the type being defined: it is in <code>types</code>. <code>not</code> returns a boolean, so a value of the defined type: it is an internal operation. In the stack, on the contrary, boolean is predefined and <code>isempty : stack → boolean</code> is an observer. Finally, <code>not</code> is defined for true as well as for false: it is not partial.' },
    'taa-c1-23': { q: 'The same type can be defined in one specification and predefined in another.',
      x: 'True. It all depends on the specification you are writing. <code>boolean</code> is defined in the Boolean type exercise (it is in <code>types</code>) and predefined in the stack type (it is in <code>uses</code>).' },
    'taa-c1-24': { q: 'How many observers does this signature have?', fig: COUNTER,
      x: 'The observers take a counter and return a predefined type: <code>value</code> (→ integer) and <code>iszero</code> (→ boolean). <code>new</code>, <code>incr</code> and <code>reset</code> return a counter: they are internal operations, and <code>new</code> is also a constant.' },
    'taa-c1-25': { q: 'In the specification of the iterative list, where is the type <code>integer</code> declared?',
      o: ['in <code>uses</code>: it is a predefined type', 'in <code>types</code>: it is a defined type', 'in <code>with</code>', 'nowhere: everyone knows it'],
      x: 'The iterative list uses integers for the ranks, but does not define them: <code>integer</code> is already designed, so it is listed in <code>uses</code>. The <code>with</code> part declares variables of type integer (<code>integer i, k</code>), not the type itself. Every predefined type you use must appear in <code>uses</code>.' },
    'taa-c1-26': { q: 'You add to the recursive list (<code>uses element</code>) the operation <code>ispresent : element × list → boolean</code>. What else must change in the specification?',
      o: ['add <code>boolean</code> to <code>uses</code>', 'add <code>boolean</code> to <code>types</code>', 'nothing: everyone knows boolean', 'add <code>boolean b</code> to <code>with</code>'],
      x: 'The profile uses the boolean type, which already exists: it is a predefined type, to be listed in <code>uses</code>, which only contained <code>element</code>. It does not go in <code>types</code>, since you do not define it. The <code>with</code> part only gives the types of the variables of the axioms.' },
    'taa-c1-27': { q: 'In the recursive list, the operation <code>ispresent : element × list → boolean</code> is…',
      o: ['an observer: an argument of type list and a boolean result', 'an internal operation: it has an argument of type list', 'a constant', 'neither: its first argument is an element'],
      x: 'One argument of a defined type (the list) and a result of a predefined type (boolean) are enough: it is an observer. The order of the arguments does not matter. It is not an internal operation: it does not return a list.' },

    /* ---------- preconditions ---------- */
    'taa-c1-28': { q: 'What do you call an operation that is not defined everywhere?',
      o: ['a partial operation', 'an observer', 'a constant', 'an internal operation'],
      x: 'A partial operation only makes sense for some of its arguments; its domain of definition is given in the preconditions. Partial says nothing about internal or observer: <code>pop</code> (internal) and <code>top</code> (observer) are both partial.' },
    'taa-c1-29': { q: 'What does <code>pop(s) is-defined-iaoi isempty(s) = false</code> mean?',
      o: ['<code>pop(s)</code> makes sense if and only if the stack s is not empty', '<code>pop(s)</code> returns false when s is empty', '<code>pop(s)</code> always returns an empty stack', '<code>pop(s)</code> empties the stack s if it was not empty'],
      x: '“iaoi” reads “if and only if”. The precondition gives the domain of definition: you do not pop an empty stack. It says nothing about the result, which is the job of the axioms; and <code>pop</code> returns a stack, never a boolean.' },
    'taa-c1-30': { q: 'You must write a precondition for every operation of the signature.',
      x: 'False. Preconditions only concern partial operations. <code>push</code>, <code>cons</code> or <code>length</code> are defined everywhere: they have no precondition.' },
    'taa-c1-31': { q: 'To define <code>search : element × list → box</code>, you add <code>ispresent : element × list → boolean</code> and write <code>search(e, λ) is-defined-iaoi ispresent(e, λ) = true</code>. What do you call an operation like <code>ispresent</code>, used to express the domain of definition of another one?',
      o: ['an auxiliary operation', 'a partial operation', 'a constant', 'a precondition'],
      x: '<code>ispresent</code> is used to write the precondition of <code>search</code>: it is an auxiliary operation. It is not partial: it answers for every element and every list; the partial one is <code>search</code>. It is not a constant, since it has two arguments. And the precondition is the whole <code>is-defined-iaoi</code> line, not the operation it uses.' },
    'taa-c1-32': { q: 'In the vector type, <code>nth(v, i) is-defined-iaoi lowerlimit(v) ≤ i ≤ upperlimit(v) &amp; isinit(v, i) = true</code>. Is the term <code>nth(modifynth(vect(1, 5), 2, a), 3)</code> defined?',
      o: ['no: cell 3 has never been given a value', 'yes: 3 is between the limits 1 and 5', 'yes, and it is a', 'no: 3 is outside the limits'],
      x: '3 is indeed between lowerlimit = 1 and upperlimit = 5, but cell 3 must also be initialized. Yet <code>modifynth</code> only filled cell 2: <code>isinit(modifynth(vect(1, 5), 2, a), 3) = isinit(vect(1, 5), 3) = false</code>. Both conditions of the precondition must be true.' },

    /* ---------- axioms ---------- */
    'taa-c1-33': { q: 'How do you write the axioms that define the internal operations?',
      o: ['by applying the observers to the internal operations', 'by applying the internal operations to the observers', 'by giving an example value for each operation', 'by copying the preconditions with an = sign'],
      x: 'To know what an internal operation does, you apply its observers to it: <code>top(push(s, e)) = e</code> applies the observer <code>top</code> to the internal operation <code>push</code>. The observer is outside, the internal operation inside. An example only holds for one value; an axiom holds for all of them.' },
    'taa-c1-34': { q: 'Which properties must the set of axioms satisfy?',
      o: ['consistency', 'completeness', 'recursion', 'commutativity'],
      x: 'Consistency: no contradictory axioms. Completeness: having written enough axioms. These are the two problems to watch when designing the axioms. Recursion and commutativity are not requirements of the course: an axiom can be recursive, like the one for <code>concatenate</code>, but it does not have to be.' },
    'taa-c1-35': { q: 'A set of axioms is <em>consistent</em> when…',
      o: ['no axiom contradicts another one', 'there are enough axioms', 'every operation has a precondition', 'every axiom contains an implication ⇒'],
      x: 'Consistency means no contradictory axioms: you must never be able to compute two different values for the same term. “Enough axioms” is completeness, the other property.' },
    'taa-c1-36': { q: 'In the stack type, the axiom <code>isempty(emptystack) = true</code> is forgotten. What is the problem?',
      o: ['a lack of completeness: nothing gives the value of <code>isempty(emptystack)</code> any more', 'a lack of consistency: two axioms contradict each other', 'none: this value is obvious', 'a precondition problem: <code>isempty</code> becomes partial'],
      x: 'An axiom is missing: you can no longer compute the observer <code>isempty</code> on the internal operation <code>emptystack</code>. It is a completeness problem. Consistency is about axioms that contradict each other, not about missing axioms. And nothing is “obvious”: only the axioms say what the operations give.' },
    'taa-c1-37': { q: 'In the queue type, you replace <code>isempty(q) = true ⇒ first(enqueue(q, e)) = e</code> with <code>first(enqueue(q, e)) = e</code>, with no condition, and you keep <code>isempty(q) = false ⇒ first(enqueue(q, e)) = first(q)</code>. What problem appears?',
      o: ['a lack of consistency: for a non-empty queue q, the two axioms can give two different values', 'a lack of completeness: the empty queue case is no longer covered', 'none: the two axioms say the same thing', 'a precondition problem: <code>first</code> becomes defined everywhere'],
      x: 'Take q = <code>enqueue(emptyqueue, a)</code> and e = b: the unconditional axiom gives b, the other one gives <code>first(q)</code>, that is a. Two values for the same term: a consistency problem. The empty queue case is still covered, by the unconditional axiom. That is why the course writes <code>isempty(q) = true ⇒</code> in front of the first one.' },
    'taa-c1-38': { q: 'In a wrong version of the vector type, you find these two axioms. What is wrong with them?', fig: VECT_IJ,
      o: ['they contradict each other when j = i: <code>i ≠ j</code> is missing from the second one (consistency)', 'the case j = i is covered by no axiom (completeness)', 'nothing: they are correct', 'the second one should be a precondition'],
      x: 'For j = i, the second axiom gives <code>isinit(modifynth(v, i, e), i) = isinit(v, i)</code>, which can be false, while the first one says true. Two contradictory axioms: a consistency problem. The fix adds <code>&amp; i ≠ j</code> to the second one. The case j = i is not forgotten; on the contrary, it is handled twice.' },
    'taa-c1-39': { q: 'In the vector type, you remove the axiom <code>isinit(vect(i, j), k) = false</code>. Which term can you no longer compute?',
      o: ['<code>isinit(vect(1, 5), 3)</code>', '<code>lowerlimit(vect(1, 5))</code>', '<code>nth(modifynth(vect(1, 5), 3, a), 3)</code>', 'none: the other axioms are enough'],
      x: 'Without this axiom, the observer <code>isinit</code> is no longer applied to the internal operation <code>vect</code>: nothing says whether a cell of a new vector is initialized. It is a completeness problem. <code>lowerlimit(vect(1, 5)) = 1</code> and <code>nth(modifynth(vect(1, 5), 3, a), 3) = a</code> can still be computed with their own axioms.' },
    'taa-c1-40': { q: 'What does the axiom <code>length(insert(λ, k, e)) = length(λ) + 1</code> say?',
      o: ['that an insertion adds exactly one element', 'that e is placed in last position', 'that <code>insert</code> is defined for every k', 'that the resulting list contains k + 1 elements'],
      x: 'The observer <code>length</code>, applied to the internal operation <code>insert</code>, says that the resulting list has one more element than λ. The position of e is given by the axioms of <code>nth</code>, the domain of k by the precondition. The rank k says nothing about the length.' },
    'taa-c1-41': { q: 'With the axioms <code>not(true) = false</code> and <code>not(false) = true</code>, what is <code>not(not(false))</code>?',
      o: ['false', 'true', 'undefined', '<code>not(false)</code>'],
      x: 'Rewrite from the inside out: <code>not(false) = true</code>, then <code>not(true) = false</code>. <code>not(false)</code> is not a finished answer: it rewrites to true, which is not the value of the term.' },
    'taa-c1-42': { q: 'For <code>not : boolean → boolean</code>, you write only one axiom: <code>not(true) = false</code>. What is missing?',
      o: ['an axiom for <code>not(false)</code>: the specification is not complete', 'nothing: <code>not(false) = true</code> follows from the first axiom', 'a precondition on <code>not</code>', 'nothing, but this axiom makes the specification inconsistent'],
      x: 'No axiom lets you compute <code>not(false)</code>: you must write <code>not(false) = true</code>. It is a completeness problem. Nothing “follows” without an axiom. A single axiom cannot contradict another one, and <code>not</code> is defined everywhere: no precondition.' },
    'taa-c1-43': { q: 'In the axiom <code>1 ≤ i &lt; k ⇒ nth(delete(λ, k), i) = nth(λ, i)</code>, what does the part left of ⇒ represent?',
      o: ['the condition under which the equality holds', 'the precondition of <code>delete</code>', 'the result of <code>nth</code>', 'the type of the variables i and k'],
      x: 'An axiom can be conditional: the equality only holds if the condition left of ⇒ is true. Here, it only concerns the ranks i before k. It is not the precondition of <code>delete</code>, which is in the <code>preconditions</code> part: the condition is about i, the rank being observed. The types are in <code>with</code>.' },
    'taa-c1-44': { q: 'The stack axioms say nothing about <code>top(emptystack)</code>. Is that a completeness problem?',
      o: ['no: the precondition of <code>top</code> excludes this term', 'yes: you must add <code>top(emptystack) = false</code>', 'yes: you must add <code>top(emptystack) = emptystack</code>', 'no: <code>top(emptystack)</code> is true by default'],
      x: '<code>top(s) is-defined-iaoi isempty(s) = false</code>: <code>top(emptystack)</code> does not exist, so no axiom has to describe it. Both proposed axioms would be wrong anyway: <code>top</code> returns an element, neither a boolean nor a stack.' },
    'taa-c1-45': { q: 'To rewrite <code>top(pop(push(push(emptystack, a), b)))</code>, which axiom do you apply first, and to which part?',
      o: ['<code>pop(push(s, e)) = s</code>, to <code>pop(push(push(emptystack, a), b))</code>', '<code>top(push(s, e)) = e</code>, to the whole term: it is b', '<code>top(push(s, e)) = e</code>, to <code>top(push(emptystack, a))</code>', '<code>isempty(push(s, e)) = false</code>, to <code>push(emptystack, a)</code>'],
      x: 'The whole term does not have the form <code>top(push(…))</code>: under <code>top</code>, there is a <code>pop</code>. The only part with the form of the left side of an axiom is <code>pop(push(push(emptystack, a), b))</code>, with s = <code>push(emptystack, a)</code> and e = b; it becomes <code>push(emptystack, a)</code>. The part <code>top(push(emptystack, a))</code> only appears after this rewriting, and it is a. <code>isempty</code> appears nowhere in the term.' },

    /* ================= chapter 2: lists ================= */
    /* ---------- recursive lists ---------- */
    'taa-c2-01': { q: 'How do you write the list λ = {e1, e2, e3} with the operations of the recursive list?',
      o: ['<code>cons(e1, cons(e2, cons(e3, emptylist)))</code>', '<code>cons(e3, cons(e2, cons(e1, emptylist)))</code>', '<code>cons(cons(cons(emptylist, e1), e2), e3)</code>', '<code>cons(e1, e2, e3)</code>'],
      x: '<code>cons(e, λ)</code> adds e at the head of λ. The term reads in the order of the list: e1 at the head, then e2, then e3, and <code>emptylist</code> at the end. The last two expressions do not follow the profile <code>cons : element × list → list</code> (an element, then a list).' },
    'taa-c2-02': { q: 'What is <code>tail(cons(a, cons(b, cons(c, emptylist))))</code>?',
      o: ['<code>cons(b, cons(c, emptylist))</code>', 'a', '<code>cons(a, cons(b, emptylist))</code>', '<code>cons(c, emptylist)</code>'],
      x: '<code>tail(cons(e, λ)) = λ</code>: you remove the head element and keep the rest of the list. The result is a list, not an element (<code>first</code> would return a). And it is the head that is removed, not the last element.' },
    'taa-c2-03': { q: 'In a recursive list, which element is directly accessible?',
      o: ['only the head element', 'all the elements, by their rank', 'only the last element', 'the first and the last'],
      x: 'Only the head element is directly accessible, with <code>first</code>. To read the third one, you go through <code>tail</code> twice: <code>first(tail(tail(λ)))</code>. Direct access by rank is the iterative list.' },
    'taa-c2-04': { q: 'λ = <code>cons(a, cons(b, cons(c, cons(d, emptylist))))</code>. How many times must you apply <code>tail</code> to λ so that <code>first</code> of the result gives d?',
      x: 'd is the 4th element: you must remove the three before it, <code>first(tail(tail(tail(λ)))) = d</code>. With four <code>tail</code>, you would get <code>emptylist</code>, and <code>first(emptylist)</code> is not defined.' },
    'taa-c2-05': { q: 'What is <code>contents(next(head(cons(a, cons(b, cons(c, emptylist))))))</code>?',
      o: ['b', 'a', 'c', 'undefined: <code>next</code> does not apply to a head'],
      x: 'Let λ = <code>cons(a, cons(b, cons(c, emptylist)))</code>. The axiom <code>next(head(λ)) = head(tail(λ))</code> says that the box after the head is the head of the tail. Then <code>first(λ) = contents(head(λ))</code> gives <code>contents(head(tail(λ))) = first(tail(λ)) = b</code>. a would be <code>contents(head(λ))</code>, without <code>next</code>.' },
    'taa-c2-06': { q: 'In a list, what does the order of the elements depend on?',
      o: ['on the position of each element in the list', 'on the values of the elements: a list is always sorted', 'on the alphabetical order of the elements', 'on nothing: as in a set, order does not matter'],
      x: 'The elements are stored one after the other in boxes: the order does not depend on the elements themselves, but on their position in the list. So a list does not have to be sorted. It is in a set, not in a list, that order does not matter at all.' },
    'taa-c2-07': { q: 'A recursive list is…',
      o: ['either empty (<code>emptylist</code>), or an element followed by a list (<code>cons(e, λ)</code>)', 'a set of elements numbered from 1', 'either empty, or reduced to a single element', 'a sequence of boxes without elements'],
      x: 'It is a recursive definition: a non-empty list contains a smaller list, its tail. Numbered ranks are the iterative list. A single element is written <code>cons(e, emptylist)</code>: it is a special case of the second form.' },
    'taa-c2-08': { q: 'What are the two ways of describing a list in the course?',
      o: ['recursively and iteratively', 'as a stack and as a queue', 'with or without boxes', 'sorted or unsorted'],
      x: 'A list is described either recursively (<code>emptylist</code>, <code>cons</code>, <code>tail</code>, <code>first</code>), or iteratively, by rank (<code>nth</code>, <code>length</code>, <code>insert</code>, <code>delete</code>). Stacks and queues are other types.' },
    'taa-c2-09': { q: 'How do you read the 3rd element of a list λ, first with the recursive list, then with the iterative list?',
      o: ['<code>first(tail(tail(λ)))</code>, then <code>nth(λ, 3)</code>', '<code>first(tail(tail(tail(λ))))</code>, then <code>nth(λ, 3)</code>', '<code>nth(λ, 3)</code> in both cases', '<code>first(tail(tail(λ)))</code>, then <code>nth(λ, 2)</code>'],
      x: 'It is the same data, read in two ways. In the recursive list, only the head is accessible: two <code>tail</code> remove the first two elements, then <code>first</code> reads the head; three <code>tail</code> would lead to the 4th element. In the iterative list, every element is accessible by its rank, and ranks start at 1: <code>nth(λ, 3)</code>. The recursive list has no <code>nth</code> operation.' },
    'taa-c2-10': { q: 'You define <code>length : list → integer</code> on the recursive list with two axioms. The first one is <code>length(emptylist) = 0</code>. What is the second one?',
      o: ['<code>length(cons(e, λ)) = length(λ) + 1</code>', '<code>length(cons(e, λ)) = 1</code>', '<code>length(cons(e, λ)) = length(λ)</code>', '<code>length(cons(e, λ)) = length(tail(λ)) + 1</code>'],
      x: 'You handle the two possible forms of a list: <code>emptylist</code> and <code>cons(e, λ)</code>. <code>cons(e, λ)</code> has one more element than λ. “= 1” only holds if λ is empty. The option with <code>length(tail(λ)) + 1</code> counts one element too few, and uses <code>tail(λ)</code>, which is not defined if λ is empty.' },
    'taa-c2-11': { q: 'With these axioms, what is <code>concatenate(cons(a, cons(b, emptylist)), cons(c, emptylist))</code>?', fig: CONCAT,
      o: ['<code>cons(a, cons(b, cons(c, emptylist)))</code>', '<code>cons(c, cons(a, cons(b, emptylist)))</code>', '<code>cons(b, cons(a, cons(c, emptylist)))</code>', '<code>cons(a, cons(b, emptylist))</code>'],
      x: 'The second axiom takes out the head a, then b: you get <code>cons(a, cons(b, concatenate(emptylist, cons(c, emptylist))))</code>. The first axiom finishes: <code>concatenate(emptylist, cons(c, emptylist)) = cons(c, emptylist)</code>. The elements of the first list stay in front, in their order.' },
    'taa-c2-12': { q: 'To define <code>ispresent</code> on the recursive list, one axiom is missing (in place of the ???). Which one?', fig: PRESENT,
      o: ['<code>e ≠ e′ ⇒ ispresent(e, cons(e′, λ)) = ispresent(e, λ)</code>', '<code>e ≠ e′ ⇒ ispresent(e, cons(e′, λ)) = false</code>', '<code>ispresent(e, cons(e′, λ)) = ispresent(e, λ)</code>', '<code>e ≠ e′ ⇒ ispresent(e′, λ) = true</code>'],
      x: 'If the head is not e, e can still be further on: you continue the search in λ. Answering false stops the search at the first different head. Without the condition e ≠ e′, the third axiom would contradict the second one when e = e′ and e is not in λ (a consistency problem).' },
    'taa-c2-13': { q: 'With these axioms, what is <code>last(cons(a, cons(b, cons(c, emptylist))))</code>?', fig: LAST,
      o: ['c', 'a', 'b', '<code>cons(c, emptylist)</code>'],
      x: 'As long as the tail is not empty, the second axiom removes the head: <code>last(cons(b, cons(c, emptylist)))</code>, then <code>last(cons(c, emptylist))</code>. The first axiom then gives c. <code>last</code> returns an element, not a list.' },
    'taa-c2-14': { q: 'With these axioms, what is <code>mystery(cons(a, cons(b, cons(a, cons(c, emptylist)))), a)</code>?', fig: MYST_REC,
      o: ['<code>cons(b, cons(c, emptylist))</code>', '<code>cons(b, cons(a, cons(c, emptylist)))</code>', '<code>cons(a, cons(a, emptylist))</code>', '<code>cons(c, cons(b, emptylist))</code>'],
      x: 'Each head equal to x is skipped, the others are kept in order: <code>mystery</code> deletes <em>all</em> the occurrences of x. Keeping the second a means stopping after the first deletion; but the second axiom goes on with <code>mystery(λ, x)</code>.' },
    'taa-c2-15': { q: 'λ is a non-empty recursive list. What is <code>cons(first(λ), tail(λ))</code>?',
      o: ['λ', '<code>tail(λ)</code>', '<code>cons(first(λ), λ)</code>', 'undefined'],
      x: 'A non-empty λ is written <code>cons(e, λ′)</code>. Then <code>first(λ) = e</code> and <code>tail(λ) = λ′</code>: you rebuild <code>cons(e, λ′)</code>, that is λ. The term is defined because λ is not empty: otherwise neither <code>first</code> nor <code>tail</code> would be.' },
    'taa-c2-16': { q: 'With <code>contents : box → element</code> and <code>next : box → box</code>, which statements are true?',
      o: ['<code>contents(p)</code> gives the element stored in box p', '<code>next(p)</code> gives the box that follows p', '<code>next(p)</code> gives the element that follows the one in p', '<code>contents(p)</code> gives the rank of box p'],
      x: 'The profiles say it: <code>contents</code> returns an element, <code>next</code> returns a box. To read the next element, you combine both: <code>contents(next(p))</code>. This is the point of the erratum of the video on iterative lists: <code>next : box → box</code>. And <code>contents</code> returns an element, not a rank: the rank is the integer you give to <code>access</code> to get a box.' },

    /* ---------- preconditions on lists ---------- */
    'taa-c2-17': { q: 'In a recursive list, what is <code>tail(emptylist)</code>?',
      o: ['nothing: this term is not defined', '<code>emptylist</code>', '0', 'false'],
      x: '<code>tail(λ) is-defined-iaoi λ ≠ emptylist</code>. The trap: thinking that the tail of an empty list is still the empty list. There is no head element to remove, so no result. 0 and false are not even lists.' },
    'taa-c2-18': { q: 'λ is an iterative list of length 3. For how many values of k is the term <code>insert(λ, k, e)</code> defined?',
      x: '<code>insert(λ, k, e) is-defined-iaoi 1 ≤ k ≤ length(λ) + 1</code>, so k from 1 to 4. Rank 4 places e after the last element. Answering 3 means copying the precondition of <code>delete</code> (1 ≤ k ≤ length(λ)).' },
    'taa-c2-19': { q: 'λ = {a, b, c} is an iterative list. Which terms are defined?',
      o: ['<code>delete(λ, 3)</code>', '<code>insert(λ, 4, d)</code>', '<code>delete(λ, 4)</code>', '<code>insert(λ, 0, d)</code>', '<code>access(λ, 0)</code>'],
      x: '<code>delete</code> and <code>access</code> require 1 ≤ k ≤ length(λ) = 3; <code>insert</code> accepts 1 ≤ k ≤ 4. Rank 0 never exists: ranks start at 1.' },
    'taa-c2-20': { q: 'The term <code>insert(emptylist, 1, a)</code> is defined.',
      x: 'True. The precondition of <code>insert</code> is only 1 ≤ k ≤ length(λ) + 1, with no condition λ ≠ emptylist. With <code>length(emptylist) = 0</code>, k = 1 works: that is how you place the first element. For <code>delete</code> and <code>access</code>, on the contrary, λ ≠ emptylist is required.' },
    'taa-c2-21': { q: 'λ = {a, b, c} is an iterative list. Which of these terms is <em>not</em> defined?',
      o: ['<code>delete(delete(λ, 1), 3)</code>', '<code>delete(insert(λ, 4, d), 4)</code>', '<code>insert(delete(λ, 3), 3, d)</code>', '<code>insert(λ, 1, d)</code>'],
      x: 'After <code>delete(λ, 1)</code>, the list only has 2 elements: rank 3 no longer exists. A precondition is checked on the list the operation is applied to, not on λ. <code>insert(λ, 4, d)</code> has 4 elements, so you can delete the 4th; <code>delete(λ, 3)</code> has 2, so you can insert at rank 3 = 2 + 1.' },
    'taa-c2-22': { q: 'You add to the iterative list <code>modify : list × integer × element → list</code>: <code>modify(λ, k, e)</code> replaces the k-th element of λ with e. Which precondition gives its exact domain?',
      o: ['<code>modify(λ, k, e) is-defined-iaoi λ ≠ emptylist &amp; 1 ≤ k ≤ length(λ)</code>', '<code>modify(λ, k, e) is-defined-iaoi 1 ≤ k ≤ length(λ) + 1</code>', '<code>modify(λ, k, e) is-defined-iaoi λ ≠ emptylist</code>', '<code>modify(λ, k, e) is-defined-iaoi 0 ≤ k ≤ length(λ)</code>'],
      x: 'You can only replace an element that exists: that is the domain of <code>delete</code>. The “+ 1” of <code>insert</code> is used to add after the last element, which makes no sense for a replacement. Without a condition on k, you would accept k = 10 in a list of 3 elements; and rank 0 does not exist.' },

    /* ---------- iterative lists ---------- */
    'taa-c2-23': { q: 'λ = {10, 20, 30} is an iterative list. What is <code>nth(λ, 1)</code>?',
      o: ['10', '20', '1', 'undefined: ranks start at 0'],
      x: 'Ranks start at 1: <code>nth(λ, 1)</code> is the first element, 10. 20 would be the answer with ranks counted from 0. And <code>nth</code> returns an element, not a rank.' },
    'taa-c2-24': { q: 'λ = {a, b, c, d}. What is <code>nth(insert(λ, 2, x), 3)</code>?',
      o: ['b', 'c', 'x', 'a'],
      x: 'k = 2 &lt; i = 3 ≤ length(λ) + 1 = 5: this is the last axiom, <code>nth(insert(λ, k, e), i) = nth(λ, i − 1)</code>, so <code>nth(λ, 2) = b</code>. The new list is {a, x, b, c, d}: everything after x has moved back one rank. Answering c means forgetting this shift.' },
    'taa-c2-25': { q: 'λ = {a, b, c, d}. What is <code>nth(delete(λ, 2), 2)</code>?',
      o: ['c', 'b', 'a', 'd'],
      x: 'k = 2 ≤ i = 2 ≤ length(λ) − 1 = 3: <code>nth(delete(λ, k), i) = nth(λ, i + 1)</code>, so <code>nth(λ, 3) = c</code>. The list becomes {a, c, d}: the elements after the deleted rank move up one rank. b is precisely the deleted element.' },
    'taa-c2-26': { q: 'λ = {a, b, c, d}. What is <code>nth(delete(λ, 3), 2)</code>?',
      o: ['b', 'c', 'a', 'd'],
      x: 'i = 2 &lt; k = 3: this is the case <code>1 ≤ i &lt; k ⇒ nth(delete(λ, k), i) = nth(λ, i)</code>. The elements before the deleted rank do not move: <code>nth(λ, 2) = b</code>. Answering c means applying the shift outside its condition.' },
    'taa-c2-27': { q: 'λ = {a, b, c}. What is <code>nth(delete(insert(λ, 1, x), 3), 2)</code>?',
      o: ['a', 'b', 'x', 'c'],
      x: '<code>insert(λ, 1, x)</code> gives {x, a, b, c}. Deleting rank 3 removes b: {x, a, c}, whose rank 2 holds a. With the axioms: i = 2 &lt; k = 3 gives <code>nth(insert(λ, 1, x), 2)</code>; then, for <code>insert</code>, k = 1 &lt; i = 2 gives <code>nth(λ, 2 − 1) = nth(λ, 1) = a</code>.' },
    'taa-c2-28': { q: 'λ = {10, 20, 30, 40, 50}. What is <code>nth(insert(delete(λ, 1), 3, 99), 4)</code>?',
      o: ['40', '50', '30', '99'],
      x: '<code>delete(λ, 1)</code> gives {20, 30, 40, 50}. Inserting 99 at rank 3 gives {20, 30, 99, 40, 50}, whose rank 4 holds 40. The two shifts cancel out for 40: it moves up one rank, then back down one rank.' },
    'taa-c2-29': { q: 'λ = {a, b, c}. What is <code>length(insert(insert(λ, 1, x), 5, y))</code>?',
      x: 'After the first insertion, the list has 4 elements: rank 5 = 4 + 1 is allowed, and y goes at the end. Two insertions: 3 + 2 = 5. The precondition is checked on the intermediate list, not on λ.' },
    'taa-c2-30': { q: 'λ = {a, b, c, d} and p2 = <code>access(λ, 2)</code>. What is <code>contents(next(p2))</code>?',
      o: ['c', 'b', 'd', 'undefined: <code>next</code> returns an integer'],
      x: '<code>next(access(λ, k)) = access(λ, k + 1)</code>: <code>next(p2)</code> is the box of the 3rd element. Then <code>contents(access(λ, 3)) = nth(λ, 3) = c</code>. This is the example of the erratum of the video: <code>next : box → box</code> moves to the next box. b is the contents of p2 itself.' },
    'taa-c2-31': { q: 'λ = {a, b, c} is an iterative list. Which terms are equal to b?',
      o: ['<code>nth(λ, 2)</code>', '<code>contents(access(λ, 2))</code>', '<code>contents(next(access(λ, 1)))</code>', '<code>contents(next(access(λ, 2)))</code>', '<code>nth(λ, 1)</code>'],
      x: '<code>contents(access(λ, k)) = nth(λ, k)</code>: the box of rank 2 holds b. <code>next(access(λ, 1)) = access(λ, 2)</code>, so the third term is also b. <code>next(access(λ, 2))</code> is the box of rank 3, which holds c; and <code>nth(λ, 1) = a</code>.' },
    'taa-c2-32': { q: 'Which term builds the list {a, b} from <code>emptylist</code>?',
      o: ['<code>insert(insert(emptylist, 1, b), 1, a)</code>', '<code>insert(insert(emptylist, 1, a), 1, b)</code>', '<code>insert(insert(emptylist, 1, a), 3, b)</code>', '<code>insert(emptylist, 1, a, b)</code>'],
      x: 'You place b, then insert a at rank 1, in front of b: {a, b}. The second term gives {b, a}, since b is inserted in front of a. The third one is not defined: the list {a} only accepts ranks 1 and 2. The last one does not follow the profile of <code>insert</code> (three arguments).' },
    'taa-c2-33': { q: 'In the axiom <code>k &lt; i ≤ length(λ) + 1 ⇒ nth(insert(λ, k, e), i) = nth(λ, i − 1)</code>, why can i go up to length(λ) + 1?',
      o: ['the resulting list has one more element: its last rank is length(λ) + 1', 'to be able to read a rank that does not exist', 'it is a typo: it should be length(λ)', 'to include rank 0'],
      x: 'After the insertion, the list has length(λ) + 1 elements. Its last rank is therefore length(λ) + 1, and it holds the former last element of λ, <code>nth(λ, length(λ))</code>. With length(λ) as the bound, this last element would no longer be described (a completeness problem).' },
    'taa-c2-34': { q: 'An error has slipped into these axioms of <code>insert</code>. Which one?', fig: INS_WRONG,
      o: ['the second axiom must stop at i &lt; k: for i = k, it contradicts the third one', 'the third axiom is one too many', 'the fourth one should read <code>nth(λ, i + 1)</code>', 'the length should stay <code>length(λ)</code>'],
      x: 'For i = k, the second axiom gives <code>nth(λ, k)</code> and the third one gives e: two values for the same term, a consistency problem. The course writes <code>1 ≤ i &lt; k</code>. The other axioms are those of the course: after rank k, you read the element of the previous rank, i − 1, and an insertion adds one element.' },
    'taa-c2-35': { q: 'For <code>modify(λ, k, e)</code>, which replaces the k-th element with e, you already have <code>length(modify(λ, k, e)) = length(λ)</code> and <code>i = k ⇒ nth(modify(λ, k, e), i) = e</code>. Which axiom completes the specification?',
      o: ['<code>1 ≤ i ≤ length(λ) &amp; i ≠ k ⇒ nth(modify(λ, k, e), i) = nth(λ, i)</code>', '<code>i ≠ k ⇒ nth(modify(λ, k, e), i) = e</code>', '<code>nth(modify(λ, k, e), i) = nth(λ, i)</code>', '<code>1 ≤ i ≤ length(λ) &amp; i ≠ k ⇒ nth(modify(λ, k, e), i) = nth(λ, i + 1)</code>'],
      x: 'The other ranks keep their element. Without the condition i ≠ k, the third axiom would contradict <code>i = k ⇒ … = e</code> (a consistency problem). The second one would fill the whole list with e. The last one shifts the elements like <code>delete</code>, whereas <code>modify</code> changes no rank.' },
    'taa-c2-36': { q: 'λ = {a, b, c, d}. With these axioms, what is <code>mystery(λ)</code>?', fig: MYST_INV,
      o: ['<code>{d, c, b, a}</code>', '<code>{a, b, c, d}</code>', '<code>{b, c, d, a}</code>', '<code>{d, a, b, c}</code>'],
      x: 'The length does not change. For i = 1, you read rank 4 − 1 + 1 = 4 (d); for i = 2, rank 3 (c); then rank 2 (b) and rank 1 (a): <code>mystery</code> reverses the list. Always compute two or three ranks by hand before you recognize the operation.' },
    'taa-c2-37': { q: 'λ = {10, 20, 30, 40}. With these axioms, what is <code>mystery(λ)</code>?', fig: MYST_ROT,
      o: ['<code>{20, 30, 40, 10}</code>', '<code>{40, 10, 20, 30}</code>', '<code>{40, 30, 20, 10}</code>', '<code>{20, 30, 40}</code>'],
      x: 'For i from 1 to 3, you read the next rank: 20, 30, 40. The last rank gets the first element, 10. <code>mystery</code> rotates the list one step to the left. {40, 10, 20, 30} would be a rotation the other way; {20, 30, 40} forgets that the length does not change.' },
    'taa-c2-38': { q: 'λ = {10, 20, 30, 40, 50}. With these axioms, what is <code>mystery(λ, 2, 4)</code>?', fig: MYST_SWAP,
      o: ['<code>{10, 40, 30, 20, 50}</code>', '<code>{10, 20, 30, 40, 50}</code>', '<code>{10, 30, 40, 20, 50}</code>', '<code>{10, 20, 50, 40, 30}</code>'],
      x: 'At rank x = 2, you read the former rank y = 4 (40); at rank y = 4, the former rank x = 2 (20). The other ranks do not move: <code>mystery</code> swaps two elements. {10, 20, 50, 40, 30} swaps ranks 3 and 5: an index shift. If x = y, the first two axioms of <code>nth</code> give the same value: they do not contradict each other.' },
    'taa-c2-39': { q: 'λ is a list of length 9. With these axioms, what is <code>length(mystery(λ, 3, 5))</code>?', fig: MYST_DEL,
      x: 'The length axiom gives 9 − 5 + 3 − 1 = 6. Ranks 1 and 2 are kept, then rank 3 reads the former rank 3 + 5 − 3 + 1 = 6: ranks 3 to 5 have disappeared. <code>mystery</code> deletes the elements of ranks x to y, that is y − x + 1 = 3 elements.' },
    'taa-c2-40': { q: 'λ = {2, 4, 6, 8, 10, 12, 14}. With these axioms, what is <code>mystery(λ, 2, 4)</code>?', fig: MYST_DEL,
      o: ['<code>{2, 10, 12, 14}</code>', '<code>{4, 6, 8}</code>', '<code>{2, 12, 14}</code>', '<code>{2, 4, 10, 12, 14}</code>'],
      x: 'Length: 7 − 4 + 2 − 1 = 4. Rank 1 does not move (1 &lt; x = 2): 2. For i from 2 to 4, you read the former rank i + 4 − 2 + 1 = i + 3, that is ranks 5, 6 and 7: 10, 12, 14. Ranks 2 to 4 (4, 6, 8) have been deleted; {4, 6, 8} is what was removed, not what is left.' },
    'taa-c2-41': { q: 'With these axioms, which term is <code>mystery(λ, e)</code> equal to?', fig: MYST_END,
      o: ['<code>insert(λ, length(λ) + 1, e)</code>', '<code>insert(λ, 1, e)</code>', '<code>insert(λ, length(λ), e)</code>', '<code>delete(λ, length(λ))</code>'],
      x: 'One more element, the old ranks unchanged, and e at the last rank: <code>mystery</code> adds e at the end of the list. It is the insertion at rank length(λ) + 1. At rank length(λ), e would come before the former last element; at rank 1, in front of all the others.' },

    /* ================= chapter 3: stacks, queues, sets ================= */
    /* ---------- stacks ---------- */
    'taa-c3-01': { q: 'A stack is a structure…',
      o: ['LIFO: the last element in is the first one out', 'FIFO: the first element in is the first one out', 'where each element is accessed by its rank', 'with no order, like a set'],
      x: 'Last In First Out: elements go in and out on the same side, the top. FIFO is the queue. Access by rank is the iterative list.' },
    'taa-c3-02': { q: 'What is <code>top(push(push(push(emptystack, a), b), c))</code>?',
      o: ['c', 'a', 'b', '<code>push(emptystack, c)</code>'],
      x: '<code>top(push(s, e)) = e</code>: the top is the last element pushed, the one in the outermost <code>push</code>. Answering a means reasoning like a queue. And <code>top</code> returns an element, not a stack.' },
    'taa-c3-03': { q: 'What is <code>top(pop(push(push(emptystack, a), b)))</code>?',
      o: ['a', 'b', 'undefined', '<code>push(emptystack, a)</code>'],
      x: '<code>pop(push(s, e)) = s</code>: <code>pop(push(push(emptystack, a), b)) = push(emptystack, a)</code>. Then <code>top(push(emptystack, a)) = a</code>. b has just been popped.' },
    'taa-c3-04': { q: 'What is <code>isempty(pop(pop(push(push(emptystack, a), b))))</code>?',
      o: ['true', 'false', 'undefined', '<code>emptystack</code>'],
      x: 'The two <code>pop</code> cancel the two <code>push</code>: you are back to <code>emptystack</code>, and <code>isempty(emptystack) = true</code>. Each <code>pop</code> applies to a non-empty stack, so everything is defined. <code>isempty</code> returns a boolean, not a stack.' },
    'taa-c3-05': { q: 'What is <code>top(pop(push(emptystack, a)))</code>?',
      o: ['undefined', 'a', '<code>emptystack</code>', 'false'],
      x: '<code>pop(push(emptystack, a)) = emptystack</code>. What remains is <code>top(emptystack)</code>: the precondition <code>isempty(s) = false</code> does not hold, so the term has no value. That does not make it false: <code>top</code> returns an element, never a boolean.' },
    'taa-c3-06': { q: 'On an empty stack, you push a, then b, then c; you pop twice; then you push d. Which stack do you get?',
      o: ['<code>push(push(emptystack, a), d)</code>', '<code>push(push(emptystack, c), d)</code>', '<code>push(push(emptystack, d), a)</code>', '<code>push(emptystack, d)</code>'],
      x: 'Each <code>pop</code> removes the last element pushed: c, then b. a remains, and d is pushed on it. <code>push(push(emptystack, c), d)</code> removes the first two elements in, like a queue. In the term, the top is the element of the outermost <code>push</code>.' },
    'taa-c3-07': { q: 'What is a stack used for?',
      o: ['reversing the order of elements', 'evaluating expressions', 'simulating the call stack (making a recursive algorithm iterative)', 'keeping the order of arrival, like a waiting line', 'traversing a tree breadth-first'],
      x: 'These are the three uses given by the course. Keeping the order of arrival (buffers, waiting lines) and breadth-first traversal are uses of the queue.' },
    'taa-c3-08': { q: 'You push a, b, c on an empty stack, then pop until it is empty, writing down each top just before popping it. In which order are the elements written down?',
      o: ['c, b, a', 'a, b, c', 'c, a, b', 'b, c, a'],
      x: 'The last one in is the first one out: c, then b, then a. That is why a stack is used to reverse the order of elements.' },
    'taa-c3-09': { q: 'The axiom <code>pop(push(s, e)) = s</code> also holds when s is the empty stack.',
      x: 'True. The axiom has no condition: <code>pop(push(emptystack, e)) = emptystack</code>. The precondition of <code>pop</code> is about <code>push(s, e)</code>, which is never empty, not about s.' },
    'taa-c3-10': { q: 'What is <code>top(push(pop(push(push(emptystack, a), b)), top(push(emptystack, c))))</code>?',
      o: ['c', 'a', 'b', 'undefined'],
      x: 'First compute the arguments: <code>pop(push(push(emptystack, a), b)) = push(emptystack, a)</code> and <code>top(push(emptystack, c)) = c</code>. The term becomes <code>top(push(push(emptystack, a), c))</code>, which is c, the last element pushed.' },
    'taa-c3-11': { q: 'How many elements does the stack <code>pop(push(pop(push(push(emptystack, a), b)), c))</code> contain?',
      x: 'From the inside out: you push a and b, pop b, push c, pop c. a remains. With the axiom <code>pop(push(s, e)) = s</code> applied twice, you get <code>push(emptystack, a)</code>.' },
    'taa-c3-12': { q: 'In the stack type, which operations have a precondition?',
      o: ['<code>pop</code>', '<code>top</code>', '<code>push</code>', '<code>isempty</code>', '<code>emptystack</code>'],
      x: '<code>pop</code> and <code>top</code> are partial: on an empty stack, there is nothing to remove or to read. You can always push, <code>isempty</code> answers for every stack, and <code>emptystack</code> has no argument.' },
    'taa-c3-13': { q: 'Only one of these stack axioms is wrong. Which one?',
      o: ['<code>pop(push(s, e)) = e</code>', '<code>top(push(s, e)) = e</code>', '<code>isempty(emptystack) = true</code>', '<code>isempty(push(s, e)) = false</code>'],
      x: '<code>pop</code> returns a stack: the right axiom is <code>pop(push(s, e)) = s</code>. Writing “= e” equates a stack and an element, which makes no sense: both sides of an axiom have the same type. It is <code>top</code> that returns e.' },
    'taa-c3-14': { q: '<code>top</code> is partial, yet the axiom <code>top(push(s, e)) = e</code> has no condition. Why?',
      o: ['<code>push(s, e)</code> is never empty, so the precondition of <code>top</code> always holds', 'because <code>top</code> is an observer', 'it needs one: <code>isempty(s) = false ⇒</code>', 'because axioms never take preconditions into account'],
      x: '<code>isempty(push(s, e)) = false</code> for every stack s: you can always read the top of a stack you have just filled. Adding <code>isempty(s) = false ⇒</code> would lose the case s = emptystack, whereas <code>top(push(emptystack, e)) = e</code>. Being an observer has nothing to do with it.' },

    /* ---------- queues ---------- */
    'taa-c3-15': { q: 'A queue is a structure…',
      o: ['FIFO: the first element in is the first one out', 'LIFO: the last element in is the first one out', 'where each element is accessed by its rank', 'where elements are added and removed on the same side'],
      x: 'First In First Out, like a waiting line: you add at the back (<code>enqueue</code>) and remove at the front (<code>dequeue</code>), at the two ends. Going in and out on the same side is the stack (LIFO).' },
    'taa-c3-16': { q: 'What is <code>first(enqueue(enqueue(enqueue(emptyqueue, a), b), c))</code>?',
      o: ['a', 'c', 'b', 'undefined'],
      x: 'The first of a queue is the element that went in first, the one in the innermost <code>enqueue</code>. With the axioms: the queue under c is not empty, so <code>first(enqueue(q, c)) = first(q)</code>; you go down like this to <code>first(enqueue(emptyqueue, a)) = a</code>. Answering c means reasoning like a stack.' },
    'taa-c3-17': { q: 'What is <code>first(dequeue(enqueue(enqueue(emptyqueue, a), b)))</code>?',
      o: ['b', 'a', 'undefined', '<code>enqueue(emptyqueue, b)</code>'],
      x: 'The queue under b, <code>enqueue(emptyqueue, a)</code>, is not empty: <code>dequeue(enqueue(q, b)) = enqueue(dequeue(q), b)</code>. And <code>dequeue(enqueue(emptyqueue, a)) = emptyqueue</code>. You get <code>enqueue(emptyqueue, b)</code>, whose first is b: <code>dequeue</code> removes the first one in, here a.' },
    'taa-c3-18': { q: 'What is <code>dequeue(enqueue(enqueue(enqueue(emptyqueue, a), b), c))</code>?',
      o: ['<code>enqueue(enqueue(emptyqueue, b), c)</code>', '<code>enqueue(enqueue(emptyqueue, a), b)</code>', '<code>enqueue(enqueue(emptyqueue, c), b)</code>', '<code>enqueue(emptyqueue, c)</code>'],
      x: 'The last axiom moves <code>dequeue</code> down under the <code>enqueue</code>: <code>dequeue(enqueue(q, c)) = enqueue(dequeue(q), c)</code> as long as q is not empty, down to <code>dequeue(enqueue(emptyqueue, a)) = emptyqueue</code>. b then c remain, in order of arrival. Removing c is the behavior of a stack.' },
    'taa-c3-19': { q: 'Why are the axioms that give <code>first(enqueue(q, e))</code> conditional?',
      o: ['the result depends on q: if q is empty, e becomes the first; otherwise the first stays that of q', 'because <code>first</code> is an observer', 'because <code>enqueue</code> is a partial operation', 'to avoid writing the axioms of <code>isempty</code>'],
      x: 'You enqueue at the back: the new element is the first only if the queue was empty. So you need two axioms, one under <code>isempty(q) = true</code>, the other under <code>isempty(q) = false</code>. <code>enqueue</code> is defined everywhere. And <code>first</code> is indeed an observer, but so is <code>top</code>, and its axioms have no condition: so that is not the reason.' },
    'taa-c3-20': { q: 'For every queue q, <code>dequeue(enqueue(q, e)) = q</code>.',
      x: 'False: that is the stack axiom. For a non-empty queue, <code>dequeue</code> removes the first of q, not e: <code>dequeue(enqueue(q, e)) = enqueue(dequeue(q), e)</code>. For example <code>dequeue(enqueue(enqueue(emptyqueue, a), b)) = enqueue(emptyqueue, b)</code>, which is not <code>enqueue(emptyqueue, a)</code>.' },
    'taa-c3-21': { q: 'What is a queue used for?',
      o: ['keeping the order of elements', 'managing buffers (printer, keyboard)', 'traversing a tree or a graph breadth-first', 'reversing the order of elements', 'simulating the call stack'],
      x: 'These are the uses given by the course: a queue gives the elements back in their order of arrival. Reversing the order and simulating the call stack are uses of the stack.' },
    'taa-c3-22': { q: 'On an empty queue, you enqueue a, b, c; you dequeue; you enqueue d; you dequeue. Which queue do you get?',
      o: ['<code>enqueue(enqueue(emptyqueue, c), d)</code>', '<code>enqueue(enqueue(emptyqueue, a), b)</code>', '<code>enqueue(enqueue(emptyqueue, d), c)</code>', '<code>enqueue(emptyqueue, d)</code>'],
      x: 'Each <code>dequeue</code> removes the oldest element: a, then b. c then d remain, in order of arrival: c is the first. <code>enqueue(enqueue(emptyqueue, a), b)</code> is what a stack would give, removing c then d.' },
    'taa-c3-23': { q: 'What is <code>first(enqueue(dequeue(enqueue(enqueue(emptyqueue, a), b)), c))</code>?',
      o: ['b', 'c', 'a', 'undefined'],
      x: '<code>dequeue(enqueue(enqueue(emptyqueue, a), b)) = enqueue(emptyqueue, b)</code>. You enqueue c behind it: <code>enqueue(enqueue(emptyqueue, b), c)</code>. The queue under c is not empty, so the first stays b.' },
    'taa-c3-24': { q: 'You do the same thing on a stack and on a queue, both empty at the start: add a, then b, then c; remove one element; read the accessible element (<code>top</code> or <code>first</code>). What do you read?',
      o: ['b with the stack, b with the queue', 'b with the stack, c with the queue', 'a with the stack, c with the queue', 'c with the stack, a with the queue'],
      x: 'Stack: you remove c, the last one in; a, b remain and the top is b. Queue: you remove a, the first one in; b, c remain and the first is b. Same result for two different reasons: you have to do the computation, not guess.' },

    /* ---------- sets and multisets ---------- */
    'taa-c3-25': { q: 'For a set, what matters?',
      o: ['whether an element is present or not', 'the order of the elements', 'the rank of each element', 'the number of times an element was added'],
      x: 'Unlike lists, order does not matter at all in a set: only the presence of an element counts. The number of occurrences is what sets multisets apart.' },
    'taa-c3-26': { q: 'What is <code>card(add(a, add(b, add(a, emptyset))))</code>?',
      x: 'From the inside out: a is not in the empty set, card = 1; b is not there, card = 2; a is already present, so <code>x ∈ s = true ⇒ card(add(x, s)) = card(s)</code>: it stays 2. Adding an element that is already present has no effect. 3 is the answer for a multiset.' },
    'taa-c3-27': { q: 'What is <code>b ∈ delete(b, add(b, add(b, emptyset)))</code>?',
      o: ['false', 'true', 'undefined', '1'],
      x: 'The axiom <code>x = y ⇒ (x ∈ delete(y, s)) = false</code> concludes directly: after b is deleted, b is no longer in the set. Adding b twice only put one b in: a set does not count occurrences.' },
    'taa-c3-28': { q: 'What is <code>card(delete(c, add(a, add(b, emptyset))))</code>?',
      x: 'c is not in the set: <code>x ∈ s = false ⇒ card(delete(x, s)) = card(s)</code>. Deleting an absent element has no effect, the cardinality stays 2. The course chooses this behavior rather than a precondition.' },
    'taa-c3-29': { q: 'What does the axiom <code>choose(s) ∈ s = true</code> guarantee?',
      o: ['the chosen element belongs to the set', 'the chosen element is the smallest', 'the chosen element is the first one added', 'the chosen element is removed from the set'],
      x: 'The axiom only says that the returned element is in s, not which one. A set has no order: “the first one added” makes no sense. And <code>choose</code> returns an element without changing s; to enumerate, you then delete the element you have handled.' },
    'taa-c3-30': { q: 'In the set type, which operations have a precondition?',
      o: ['<code>choose</code>', '<code>delete</code>', '<code>add</code>', '<code>card</code>', '<code>_∈_</code>'],
      x: 'Only <code>choose</code> is partial: <code>choose(s) is-defined-iaoi s ≠ emptyset</code>. The course makes <code>add</code> and <code>delete</code> have no effect in case of error (element already present, element absent) rather than making them partial, and <code>card</code> is defined everywhere.' },
    'taa-c3-31': { q: 's = <code>add(a, add(b, emptyset))</code>. Which terms are true?',
      o: ['<code>a ∈ s</code>', '<code>b ∈ delete(a, s)</code>', '<code>a ∈ delete(a, s)</code>', '<code>c ∈ s</code>', '<code>choose(s) ∈ s</code>'],
      x: 'a has just been added: <code>a ∈ s</code> is true. b ≠ a, so deleting a does not affect b. <code>a ∈ delete(a, s)</code> is false, and c was never added. Finally <code>choose(s) ∈ s = true</code> is an axiom, and s is not empty.' },
    'taa-c3-32': { q: 'In a multiset, what is <code>card(add(a, add(b, add(a, emptymultiset))))</code>?',
      x: 'For a multiset, <code>card(add(x, ms)) = card(ms) + 1</code>, with no condition: every addition counts, even a duplicate. The same term for a set would give 2.' },
    'taa-c3-33': { q: 'What is <code>nboccurrences(a, delete(a, add(b, add(a, add(a, emptymultiset)))))</code>?',
      x: 'Before the deletion, a was added twice: <code>nboccurrences</code> is 2 (adding b does not count for a). Then <code>nboccurrences(x, ms) ≥ 1 ⇒ nboccurrences(x, delete(x, ms)) = nboccurrences(x, ms) − 1</code>: 2 − 1 = 1. In a multiset, delete removes only one occurrence.' },
    'taa-c3-34': { q: 'In a multiset, which statements are true?',
      o: ['adding an element that is already present increases <code>card</code> by 1', 'deleting an element present twice leaves one occurrence of it', 'the order of the elements matters', '<code>nboccurrences</code> returns a boolean'],
      x: '<code>card(add(x, ms)) = card(ms) + 1</code>, with no condition: every addition counts, even a duplicate. If x is present twice, <code>nboccurrences(x, delete(x, ms))</code> is 2 − 1 = 1: one occurrence is left. Order matters no more than in a set. And <code>nboccurrences : element × multiset → integer</code> counts the occurrences: it returns an integer.' }
  };
  /* same invisible line breaks as the French file: in <code>, a break is allowed after each opening parenthesis */
  function wrap(h) {
    return h.replace(/<code>([^<]*)<\/code>/g, function (m, c) { return '<code>' + c.replace(/\(/g, '(<wbr>') + '</code>'; });
  }
  Object.keys(Q).forEach(function (id) {
    var e = Q[id];
    if (e.q) e.q = wrap(e.q);
    if (e.x) e.x = wrap(e.x);
    if (e.o) e.o = e.o.map(wrap);
  });
  REV.i18n.qcm(Q);
})();
